def count_paths(grid):
    rows, cols = len(grid), len(grid[0])
    ways = [[0] * cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                continue
            if i == 0 and j == 0:
                ways[i][j] = 1
                continue
            up = ways[i - 1][j] if i > 0 else 0
            left = ways[i][j - 1] if j > 0 else 0
            ways[i][j] = up + left
    return ways[rows - 1][cols - 1]

def min_path_cost(costs):
    rows, cols = len(costs), len(costs[0])
    best = [[0] * cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            if i == 0 and j == 0:
                best[i][j] = costs[0][0]
            elif i == 0:
                best[i][j] = best[i][j - 1] + costs[i][j]
            elif j == 0:
                best[i][j] = best[i - 1][j] + costs[i][j]
            else:
                best[i][j] = min(best[i - 1][j], best[i][j - 1]) + costs[i][j]
    return best[rows - 1][cols - 1]
